/* ============================================ Include required type specifiers ============================================= */

#ifndef __I
  #ifdef __cplusplus
    #define __I     volatile                         /*!< Defines 'read only' permissions                                      */
  #else
    #define __I     volatile const                   /*!< Defines 'read only' permissions                                      */
  #endif
#endif
#ifndef __O
  #define __O     volatile                           /*!< Defines 'write only' permissions                                     */
#endif
#ifndef __IO
  #define __IO    volatile                           /*!< Defines 'read / write' permissions                                   */
#endif

/* The following defines should be used for structure members */
#ifndef __IM
  #define __IM     volatile const                    /*!< Defines 'read only' structure member permissions                     */
#endif
#ifndef __OM
  #define __OM     volatile                          /*!< Defines 'write only' structure member permissions                    */
#endif
#ifndef __IOM
  #define __IOM    volatile                          /*!< Defines 'read / write' structure member permissions                  */
#endif

/* ======================================================= Domain IDs ======================================================== */
/**
  * @brief (unspecified)
  */
typedef enum {
  NRF_DOMAIN_SYSTEM                          = 0,    /*!< System                                                               */
  NRF_DOMAIN_WIFICORE                        = 8,    /*!< Wi-Fi Core                                                           */
} NRF_DOMAINID_Type;

/* ====================================================== Processor IDs ====================================================== */
/**
  * @brief (unspecified)
  */
typedef enum {
  NRF_PROCESSOR_CM33                         = 1,    /*!< Core Processor                                                       */
  NRF_PROCESSOR_VPR                          = 2,    /*!< Generic VPR Processor                                                */
  NRF_PROCESSOR_LMAC                         = 4,    /*!< Wi-Fi LMAC Processor                                                 */
  NRF_PROCESSOR_UMAC                         = 5,    /*!< Wi-Fi UMAC Processor                                                 */
} NRF_PROCESSORID_Type;

/* ======================================================== Owner IDs ======================================================== */
/**
  * @brief (unspecified)
  */
typedef enum {
  NRF_OWNER_NONE                             = 0,    /*!< Used to denote that ownership is not enforced                        */
  NRF_OWNER_APPLICATION                      = 1,    /*!< All accesses, except KMU                                             */
  NRF_OWNER_KMU                              = 2,    /*!< KMU Accesses                                                         */
} NRF_OWNERID_Type;


