  #define AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERHREADY_Msk (0xFFUL << AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERHREADY_Pos) /*!< Bit
                                                                            mask of CFGWDOGTIMERHREADY field.*/

/* CFGWDOGTIMERHGRANT @Bits 8..15 : Axon Pro will wait the programmed number of clock cyles to receive hgrant on AHB master port
                                    when requesting the bus, otherwise the watchdog timer will expire and trigger an interrupt */

  #define AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERHGRANT_Pos (8UL) /*!< Position of CFGWDOGTIMERHGRANT field.                    */
  #define AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERHGRANT_Msk (0xFFUL << AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERHGRANT_Pos) /*!< Bit
                                                                            mask of CFGWDOGTIMERHGRANT field.*/

/* CFGWDOGTIMERCMD @Bits 16..23 : Axon Pro will wait the programmed number of clock cyles * 2^16 for a command to finish
                                  processing, otherwise the watchdog timer will expire and trigger an interrupt */

  #define AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERCMD_Pos (16UL) /*!< Position of CFGWDOGTIMERCMD field.                         */
  #define AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERCMD_Msk (0xFFUL << AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERCMD_Pos) /*!< Bit mask
                                                                            of CFGWDOGTIMERCMD field.*/

/* CFGWDOGTIMERFINISH @Bits 24..31 : Axon Pro will wait the programmed number of clock cyles * 2^28 for all the command buffer
                                     to finish processing, otherwise the watchdog timer will expire and trigger an interrupt */

  #define AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERFINISH_Pos (24UL) /*!< Position of CFGWDOGTIMERFINISH field.                   */
  #define AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERFINISH_Msk (0xFFUL << AXONS_AXONNN_CFGWDOGTIMER_CFGWDOGTIMERFINISH_Pos) /*!< Bit
                                                                            mask of CFGWDOGTIMERFINISH field.*/


/* AXONS_AXONNN_CFGPMON: Performance Monitor Configuration Register */
  #define AXONS_AXONNN_CFGPMON_ResetValue (0x00000000UL) /*!< Reset value of CFGPMON register.                                 */

/* CFGPMONMODE @Bits 0..1 : Performance Monitor Mode of Operation. When disabled, sts_pmon_m/lsb_cnt is 0. When free running,
                            sts_pmon_m/lsb_cnt is incrmenting 64 bit counter. The counter will rollover and no triggering is
                            necessary. When counting events, the internal 64 bit counter will count the number of times the
                            event specified by cfg_pmon_sel_event occurs. The counter will saturate when it reaches the maximum
                            value. Once triggered by req_core_pmon_trig, sts_pmon_msb_cnt and sts_pmon_lsb_cnt will be updated
                            with the internal counter value and the internal counter will be reset. When measuring latency, the
                            internal 64 bit counter will start the latency measurment when triggered by req_core_pmon_trig. Once
                            the measurement is complete, the value will be updated to sts_pmon_msb_cnt and sts_pmon_lsb_cnt and
                            then req_core_pmon_trig will auto clear. The specific latency to measure is specifed by
                            cfg_pmon_sel_event setting. The latency can be averaged over a number of measurments as specifed by
                            cfg_pmon_average setting. The counter will saturate when maximum is reached */

  #define AXONS_AXONNN_CFGPMON_CFGPMONMODE_Pos (0UL) /*!< Position of CFGPMONMODE field.                                       */
  #define AXONS_AXONNN_CFGPMON_CFGPMONMODE_Msk (0x3UL << AXONS_AXONNN_CFGPMON_CFGPMONMODE_Pos) /*!< Bit mask of CFGPMONMODE
                                                                            field.*/
  #define AXONS_AXONNN_CFGPMON_CFGPMONMODE_Min (0x0UL) /*!< Min enumerator value of CFGPMONMODE field.                         */
  #define AXONS_AXONNN_CFGPMON_CFGPMONMODE_Max (0x3UL) /*!< Max enumerator value of CFGPMONMODE field.                         */
  #define AXONS_AXONNN_CFGPMON_CFGPMONMODE_DISABLED (0x0UL) /*!< (unspecified)                                                 */
  #define AXONS_AXONNN_CFGPMON_CFGPMONMODE_FREERUNNING (0x1UL) /*!< (unspecified)                                              */
  #define AXONS_AXONNN_CFGPMON_CFGPMONMODE_EVENTCOUNT (0x2UL) /*!< (unspecified)                                               */
  #define AXONS_AXONNN_CFGPMON_CFGPMONMODE_EVENTLATENCY (0x3UL) /*!< (unspecified)                                             */

/* CFGPMONSELEVENT @Bits 8..10 : In Free_Running mode, the first bit cfg_pmon_sel_event[0] = 1 means count the clock cycles only
                                 when AXON is active, 0 means keep counting. Otherwise cfg_pmon_sel_event selects which event to
                                 count or measure latency */

  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_Pos (8UL) /*!< Position of CFGPMONSELEVENT field.                               */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_Msk (0x7UL << AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_Pos) /*!< Bit mask of
                                                                            CFGPMONSELEVENT field.*/
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_Min (0x0UL) /*!< Min enumerator value of CFGPMONSELEVENT field.                 */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_Max (0x7UL) /*!< Max enumerator value of CFGPMONSELEVENT field.                 */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_NUMINTERRUPTCYCLES (0x0UL) /*!< (unspecified)                                   */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_NUMIDLECYCLES (0x1UL) /*!< (unspecified)                                        */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_NUMBUSYCYCLES (0x2UL) /*!< (unspecified)                                        */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_NUMFINISHEDINTERRUPTS (0x3UL) /*!< (unspecified)                                */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_NUMCOMMANDS (0x4UL) /*!< (unspecified)                                          */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_NUMCONTROLBUFFERFETCHCYCLES (0x5UL) /*!< (unspecified)                          */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_NUMCOMMANDEXECUTECYCLES (0x6UL) /*!< (unspecified)                              */
  #define AXONS_AXONNN_CFGPMON_CFGPMONSELEVENT_NUMFLUSHOUTPUTCYCLES (0x7UL) /*!< (unspecified)                                 */

/* CFGPMONAVERAGE @Bits 16..19 : Amount of averaging in latency measurement mode. Value is 2 ^ cfg_pmon_average. 0 means no
                                 averaging. 1 means average two measurements. 2 means average 4 measurements. 3 means average 8
                                 measurments, and so on */

  #define AXONS_AXONNN_CFGPMON_CFGPMONAVERAGE_Pos (16UL) /*!< Position of CFGPMONAVERAGE field.                                */
  #define AXONS_AXONNN_CFGPMON_CFGPMONAVERAGE_Msk (0xFUL << AXONS_AXONNN_CFGPMON_CFGPMONAVERAGE_Pos) /*!< Bit mask of
                                                                            CFGPMONAVERAGE field.*/


/* AXONS_AXONNN_CFGPMONAHB: Performance Monitor AHB Configuration Register */
  #define AXONS_AXONNN_CFGPMONAHB_ResetValue (0x00000000UL) /*!< Reset value of CFGPMONAHB register.                           */

/* CFGPMONAHBMODE @Bits 0..1 : Performance Monitor Mode of Operation. After writing this bit, req_core_pmon_ahb_rw must be set 1
                               to take effect. When disabled, sts_pmon_ahb_m/lsb_cnt is 0. When free running,
                               sts_pmon_ahb_m/lsb_cnt is incrmenting 64 bit counter. The counter will rollover and no triggering
                               is necessary. When counting events, the internal 64 bit counter will count the number of times
                               the event specified by cfg_pmon_ahb_sel_event occurs. The counter will saturate when it reaches
                               the maximum value. Once triggered by req_core_pmon_ahb_trig, sts_pmon_ahb_msb_cnt and
                               sts_pmon_ahb_lsb_cnt will be updated with the internal counter value and the internal counter
                               will be reset. When measuring latency, the internal 64 bit counter will start the latency
                               measurment when triggered by req_core_pmon_ahb_trig. Once the measurement is complete, the value
                               will be updated to sts_pmon_ahb_msb_cnt and sts_pmon_ahb_lsb_cnt and then req_core_pmon_ahb_trig
                               will auto clear. The specific latency to measure is specifed by cfg_pmon_ahb_sel_event setting.
                               The latency can be averaged over a number of measurments as specifed by cfg_pmon_ahb_average
                               setting. The counter will saturate when maximum is reached */

  #define AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBMODE_Pos (0UL) /*!< Position of CFGPMONAHBMODE field.                              */
  #define AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBMODE_Msk (0x3UL << AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBMODE_Pos) /*!< Bit mask of
                                                                            CFGPMONAHBMODE field.*/

/* CFGPMONAHBSELEVENT @Bits 8..10 : Select which event to count or measure latency. After writing this bit, req_core_pmon_ahb_rw
                                    must be set 1 to take effect. */

  #define AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBSELEVENT_Pos (8UL) /*!< Position of CFGPMONAHBSELEVENT field.                      */
  #define AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBSELEVENT_Msk (0x7UL << AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBSELEVENT_Pos) /*!< Bit mask
                                                                            of CFGPMONAHBSELEVENT field.*/
  #define AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBSELEVENT_Min (0x0UL) /*!< Min enumerator value of CFGPMONAHBSELEVENT field.        */
  #define AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBSELEVENT_Max (0x7UL) /*!< Max enumerator value of CFGPMONAHBSELEVENT field.        */
  #define AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBSELEVENT_NUMWRITECYCLES (0x0UL) /*!< (unspecified)                                 */
  #define AXONS_AXONNN_CFGPMONAHB_CFGPMONAHBSELEVENT_NUMREADCYCLES (0x1UL) /*!< (unspecified)                                  */
