  #define MRAMC_TEST_TESTMODE_TESTMODE_TESTMODE1 (0x0001UL) /*!< Read: In TESTMODE1.                                           */
  #define MRAMC_TEST_TESTMODE_TESTMODE_TESTMODE2 (0x0002UL) /*!< Read: In TESTMODE2.                                           */
  #define MRAMC_TEST_TESTMODE_TESTMODE_SetNORMAL (0x0000UL) /*!< Write: Sets NORMAL mode.                                      */
  #define MRAMC_TEST_TESTMODE_TESTMODE_SetTESTMODE1 (0xBCDEUL) /*!< Write: Sets TESTMODE1. Enables the mass erase.             */
  #define MRAMC_TEST_TESTMODE_TESTMODE_SetTESTMODE2 (0xABCDUL) /*!< Write: Sets TESTMODE2. Used for production tests.          */


/* MRAMC_TEST_LOCKTESTMODE: Enables the lock for the TESTMODE */
  #define MRAMC_TEST_LOCKTESTMODE_ResetValue (0x00000000UL) /*!< Reset value of LOCKTESTMODE register.                         */

/* EnableLock @Bits 0..31 : Enables the lock for TESTMODE. */
