  #define MRAMC_INTPEND_ResetValue (0x00000000UL)    /*!< Reset value of INTPEND register.                                     */

/* READY @Bit 0 : Read pending status of interrupt for event READY */
  #define MRAMC_INTPEND_READY_Pos (0UL)              /*!< Position of READY field.                                             */
