  #define PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Max (0x1UL) /*!< Max enumerator value of MINORSTEP025CUSTOM field.                */
  #define PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Disable (0x0UL) /*!< Nothing added                                                */
  #define PDM_FILTER_CTRL_MINORSTEP025CUSTOM_Enable (0x1UL) /*!< +0.25dB added                                                 */

/* MINORSTEP050CUSTOM @Bits 10..13 : Compensates Gain with +0.5dB steps */
  #define PDM_FILTER_CTRL_MINORSTEP050CUSTOM_Pos (10UL) /*!< Position of MINORSTEP050CUSTOM field.                             */
  #define PDM_FILTER_CTRL_MINORSTEP050CUSTOM_Msk (0xFUL << PDM_FILTER_CTRL_MINORSTEP050CUSTOM_Pos) /*!< Bit mask of
                                                                            MINORSTEP050CUSTOM field.*/
  #define PDM_FILTER_CTRL_MINORSTEP050CUSTOM_Min (0x0UL) /*!< Min value of MINORSTEP050CUSTOM field.                           */
  #define PDM_FILTER_CTRL_MINORSTEP050CUSTOM_Max (0xCUL) /*!< Max size of MINORSTEP050CUSTOM field.                            */

/* SOFTCYCLES @Bits 14..17 : Custom number of cycles for soft gain/mute function 32*(Multiplication+1) steps */
  #define PDM_FILTER_CTRL_SOFTCYCLES_Pos (14UL)      /*!< Position of SOFTCYCLES field.                                        */
  #define PDM_FILTER_CTRL_SOFTCYCLES_Msk (0xFUL << PDM_FILTER_CTRL_SOFTCYCLES_Pos) /*!< Bit mask of SOFTCYCLES field.          */
  #define PDM_FILTER_CTRL_SOFTCYCLES_Min (0x0UL)     /*!< Min value of SOFTCYCLES field.                                       */
  #define PDM_FILTER_CTRL_SOFTCYCLES_Max (0xFUL)     /*!< Max size of SOFTCYCLES field.                                        */

