  #define PDM_FILTER_CTRL_CHANNELSWAP_Msk (0x1UL << PDM_FILTER_CTRL_CHANNELSWAP_Pos) /*!< Bit mask of CHANNELSWAP field.       */
  #define PDM_FILTER_CTRL_CHANNELSWAP_Min (0x0UL)    /*!< Min enumerator value of CHANNELSWAP field.                           */
  #define PDM_FILTER_CTRL_CHANNELSWAP_Max (0x1UL)    /*!< Max enumerator value of CHANNELSWAP field.                           */
  #define PDM_FILTER_CTRL_CHANNELSWAP_NoSwap (0x0UL) /*!< Left to left, right to right                                         */
  #define PDM_FILTER_CTRL_CHANNELSWAP_Swap (0x1UL)   /*!< Swapped connection                                                   */

/* DATASAMPLEDELAY @Bits 19..20 : Input data sampling point delay in PDM_CLK cycels */
  #define PDM_FILTER_CTRL_DATASAMPLEDELAY_Pos (19UL) /*!< Position of DATASAMPLEDELAY field.                                   */
  #define PDM_FILTER_CTRL_DATASAMPLEDELAY_Msk (0x3UL << PDM_FILTER_CTRL_DATASAMPLEDELAY_Pos) /*!< Bit mask of DATASAMPLEDELAY
                                                                            field.*/
