  #define RADIO_AUXDATA_CNF_ACQMODE_HypBits (0x0CUL) /*!< Valid serial data from Hyper Demodulator                             */
  #define RADIO_AUXDATA_CNF_ACQMODE_AaBits (0x0DUL)  /*!< Valid serial data from AA Demodulator                                */
