  #define RADIO_AUXDATA_CNF_ACQMODE_FeMixIQ (0x12UL) /*!< Frontend IQ after decimation and downmix                             */
  #define RADIO_AUXDATA_CNF_ACQMODE_AdPllTrace (0x14UL) /*!< ADPLL tracing                                                     */

/* INJMODE @Bits 8..11 : Injection mode (data from memory written to RADIO) */
