  #define RADIO_AUXDATA_CNF_DIR_Max (0x1UL)          /*!< Max enumerator value of DIR field.                                   */
  #define RADIO_AUXDATA_CNF_DIR_Acq (0x0UL)          /*!< Peripheral to memory                                                 */
  #define RADIO_AUXDATA_CNF_DIR_Inj (0x1UL)          /*!< Memory to peripheral                                                 */



