  #define RADIO_RXGAIN_STATUS_IFPKDET_Pos (26UL)     /*!< Position of IFPKDET field.                                           */
  #define RADIO_RXGAIN_STATUS_IFPKDET_Msk (0x3UL << RADIO_RXGAIN_STATUS_IFPKDET_Pos) /*!< Bit mask of IFPKDET field.           */

