  #define WIFIPHY_SCP_DCCONTROL_DCMONITORIQSEL_Pos (1UL) /*!< Position of DCMONITORIQSEL field.                                */
  #define WIFIPHY_SCP_DCCONTROL_DCMONITORIQSEL_Msk (0x1UL << WIFIPHY_SCP_DCCONTROL_DCMONITORIQSEL_Pos) /*!< Bit mask of
                                                                            DCMONITORIQSEL field.*/
  #define WIFIPHY_SCP_DCCONTROL_DCMONITORIQSEL_Min (0x0UL) /*!< Min enumerator value of DCMONITORIQSEL field.                  */
