/* WIFIPHY_SCP_LOBASE: SCP LO BASE */
  #define WIFIPHY_SCP_LOBASE_ResetValue (0x00000000UL) /*!< Reset value of LOBASE register.                                    */

/* LOBASE @Bits 21..23 : Local Oscillator base. This is an unsigned value which is combined with LOCONTROL to generate the
                         26-bit control Fc: Fc = (LOBASE << 23) + LOCONTROL Fc is in 2's complement signed format where its
                         value represents numbers within the range -1 to 0.9999999. To convert a ratio into the 26-bit Fc,
                         multiply by 2^25. The digitally generated Local Oscillator (LO) frequency used in the mixer section is
                         equal to Fc * (IF Clock Frequency/2). Hence the full-scale negative value represents a frequency of
                         -(IF Clock Frequency/2). The input signal is frequency translated such that input frequency F moves to
                         a frequency of F + Local Oscillator (LO) Frequency. NOTE : a real IF input implicitly carries the
                         inverse of its positive spectrum at negative frequencies. This means that a positive Fc applied to a
                         real IF gives an inverted spectrum, and a negative Fc gives a non-inverted one. An SCP input contains
                         independent positive and negative frequency components, so Fc cannot invert the spectrum. */

  #define WIFIPHY_SCP_LOBASE_LOBASE_Pos (21UL)       /*!< Position of LOBASE field.                                            */
  #define WIFIPHY_SCP_LOBASE_LOBASE_Msk (0x7UL << WIFIPHY_SCP_LOBASE_LOBASE_Pos) /*!< Bit mask of LOBASE field.                */


/* WIFIPHY_SCP_LOCONTROL: SCP LO CONTROL */
  #define WIFIPHY_SCP_LOCONTROL_ResetValue (0x00000000UL) /*!< Reset value of LOCONTROL register.                              */

/* LOCONTROL @Bits 0..23 : Local Oscillator control. This is a 2's complement value which is combined with LOBASE to generate
                           the 26-bit control Fc: Fc = (LOBASE << 23) + LOCONTROL */

  #define WIFIPHY_SCP_LOCONTROL_LOCONTROL_Pos (0UL)  /*!< Position of LOCONTROL field.                                         */
  #define WIFIPHY_SCP_LOCONTROL_LOCONTROL_Msk (0xFFFFFFUL << WIFIPHY_SCP_LOCONTROL_LOCONTROL_Pos) /*!< Bit mask of LOCONTROL
                                                                            field.*/


/* WIFIPHY_SCP_MIXERBYPASS: SCP MIXER BYPASS */
  #define WIFIPHY_SCP_MIXERBYPASS_ResetValue (0x00000000UL) /*!< Reset value of MIXERBYPASS register.                          */

/* MIXERBYPASS @Bit 23 : Used to set the bypass mode of the Mixer block. When bypass is set the Mixer block is powered down and
                         data passes around it unaltered. When set to Normal the block operates as programmed by the registers
                         that control it. */

  #define WIFIPHY_SCP_MIXERBYPASS_MIXERBYPASS_Pos (23UL) /*!< Position of MIXERBYPASS field.                                   */
  #define WIFIPHY_SCP_MIXERBYPASS_MIXERBYPASS_Msk (0x1UL << WIFIPHY_SCP_MIXERBYPASS_MIXERBYPASS_Pos) /*!< Bit mask of
                                                                            MIXERBYPASS field.*/
  #define WIFIPHY_SCP_MIXERBYPASS_MIXERBYPASS_Min (0x0UL) /*!< Min enumerator value of MIXERBYPASS field.                      */
  #define WIFIPHY_SCP_MIXERBYPASS_MIXERBYPASS_Max (0x1UL) /*!< Max enumerator value of MIXERBYPASS field.                      */
  #define WIFIPHY_SCP_MIXERBYPASS_MIXERBYPASS_NormalOperation (0x0UL) /*!< Normal operation                                    */
  #define WIFIPHY_SCP_MIXERBYPASS_MIXERBYPASS_BlockBypassed (0x1UL) /*!< Block Bypassed (overrules any other block settings)   */


