  #define WIFIPHY_SCP_MIXERCONTROL_MIXEROUTGAIN_GainOf20IsAppliedTo (0x1UL) /*!< Gain of 2.0 is applied to the output of Mixer
                                                                            rotator (used to compensate for 0.5 gain in real
                                                                            input mode)*/

/* MIXERMETRICENABLE @Bit 23 : Used to enable the Mixer IQ level imbalance estimation metric generation: */
  #define WIFIPHY_SCP_MIXERCONTROL_MIXERMETRICENABLE_Pos (23UL) /*!< Position of MIXERMETRICENABLE field.                      */
  #define WIFIPHY_SCP_MIXERCONTROL_MIXERMETRICENABLE_Msk (0x1UL << WIFIPHY_SCP_MIXERCONTROL_MIXERMETRICENABLE_Pos) /*!< Bit mask
                                                                            of MIXERMETRICENABLE field.*/
