  #define WIFIPHY_SCP_GNSSOUTPUTFORMAT_GNSSOUTPUTFORMAT_Max (0x4UL) /*!< Max enumerator value of GNSSOUTPUTFORMAT field.       */
  #define WIFIPHY_SCP_GNSSOUTPUTFORMAT_GNSSOUTPUTFORMAT_1XIQPair (0x0UL) /*!< 1x I/Q pair (12-bits per component) This
                                                                            represents standard SCP operation.*/
  #define WIFIPHY_SCP_GNSSOUTPUTFORMAT_GNSSOUTPUTFORMAT_3XIQPairs (0x1UL) /*!< 3x I/Q pairs (4-bits per component)             */
  #define WIFIPHY_SCP_GNSSOUTPUTFORMAT_GNSSOUTPUTFORMAT_4XIQPairs (0x2UL) /*!< 4x I/Q pairs (3-bits per component)             */
  #define WIFIPHY_SCP_GNSSOUTPUTFORMAT_GNSSOUTPUTFORMAT_6XIQPairs (0x3UL) /*!< 6x I/Q pairs (2-bits per component)             */
  #define WIFIPHY_SCP_GNSSOUTPUTFORMAT_GNSSOUTPUTFORMAT_12XIQPairs (0x4UL) /*!< 12x I/Q pairs (1-bit per component)            */


