/* TBUSOUTPUTFORMAT @Bits 18..19 : Used to select TBus output format: */
  #define WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_Pos (18UL) /*!< Position of TBUSOUTPUTFORMAT field.                         */
  #define WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_Msk (0x3UL << WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_Pos) /*!< Bit mask of
                                                                            TBUSOUTPUTFORMAT field.*/
  #define WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_Min (0x0UL) /*!< Min enumerator value of TBUSOUTPUTFORMAT field.            */
  #define WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_Max (0x3UL) /*!< Max enumerator value of TBUSOUTPUTFORMAT field.            */
  #define WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_12BitRealInUpperAnd (0x0UL) /*!< 12-bit real in upper and 12-bit imaginary in
                                                                            lower 24 bits of TBus output (default).*/
  #define WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_Alternating16BitIma (0x1UL) /*!< Alternating 16-bit imaginary followed by
                                                                            16-bit real, left aligned in 24-bits of output TBus.
                                                                            8-bit lsbs are zero padded and full 24 bits
                                                                            transferred to memory by EDC for processing as
                                                                            24-bit double by MCP. This case is only relevant on
                                                                            16-bit SCPs. Note reference to this register in the
                                                                            description of register GNSSOUTPUTFORMAT.*/
  #define WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_Alternating16BitIma2 (0x2UL) /*!< Alternating 16-bit imaginary followed by
                                                                            16-bit real, right aligned in 24-bits of output
                                                                            TBus. Sign extended to 24 bits but in practice only
                                                                            lower 16 bits will be transferred to memory by EDC
                                                                            for processing as 32-bit complex by MCU. This case
                                                                            is only relevant on 16-bit SCPs. Note reference to
                                                                            this register in the description of register
                                                                            GNSSOUTPUTFORMAT.*/
  #define WIFIPHY_SCP_TBUSCONTROL_TBUSOUTPUTFORMAT_Alternating12BitRea (0x3UL) /*!< Alternating 12-bit real followed by 12-bit
                                                                            imaginary, where each 12-bit word is left shifted by
                                                                            4 and signed extended to 24-bits.*/

/* TBUSOUTPUTSTALL @Bit 20 : Used to enable or disable stalling of SCP when output FIFO is full: */
