  #define WIFIPHY_WIFICOREAGC_WLANAGCAACIDETCONFIG1_ADDISAPMARGINDB_Msk (0xFUL << WIFIPHY_WIFICOREAGC_WLANAGCAACIDETCONFIG1_ADDISAPMARGINDB_Pos)
                                                                            /*!< Bit mask of ADDISAPMARGINDB field.*/

