  #define WIFIPHY_WLANFFT_OFDMCONFIG2_PACKETTYPE_Legacy (0x0UL) /*!< Legacy                                                    */
  #define WIFIPHY_WLANFFT_OFDMCONFIG2_PACKETTYPE_HtMf (0x1UL) /*!< HT-MF                                                       */
