  #define WIFIPHY_WLANBITDEINT_COREIDREG_WLANBITDEINTGROUPID_Pos (16UL) /*!< Position of WLANBITDEINTGROUPID field.            */
  #define WIFIPHY_WLANBITDEINT_COREIDREG_WLANBITDEINTGROUPID_Msk (0xFFUL << WIFIPHY_WLANBITDEINT_COREIDREG_WLANBITDEINTGROUPID_Pos)
                                                                            /*!< Bit mask of WLANBITDEINTGROUPID field.*/


/* WIFIPHY_WLANBITDEINT_COREREVISIONREG: WLAN BIT DEINT CORE REVISION REG */
  #define WIFIPHY_WLANBITDEINT_COREREVISIONREG_ResetValue (0x00000000UL) /*!< Reset value of COREREVISIONREG register.         */

/* WLANBITDEINTMAINTENANCEREV @Bits 0..7 : Maintenance Release Revision */
