                                                                            /*!< Bit mask of WLANBITDEINTMAINTENANCEREV field.*/

/* WLANBITDEINTMINORREV @Bits 8..15 : Core Minor Release Revision */
  #define WIFIPHY_WLANBITDEINT_COREREVISIONREG_WLANBITDEINTMINORREV_Pos (8UL) /*!< Position of WLANBITDEINTMINORREV field.     */
  #define WIFIPHY_WLANBITDEINT_COREREVISIONREG_WLANBITDEINTMINORREV_Msk (0xFFUL << WIFIPHY_WLANBITDEINT_COREREVISIONREG_WLANBITDEINTMINORREV_Pos)
                                                                            /*!< Bit mask of WLANBITDEINTMINORREV field.*/

